ions'] as $index=>$section){echo '<article class="card manual-section" id="manual-section-'.$index.'" data-search="'.e(strtolower($section[0].' '.implode(' ',$section[1]))).'"><header><span class="manual-number">'.($index+1).'</span><div><h2>'.e($section[0]).'</h2><button type="button" class="manual-listen" data-speak-section>🔊 Escuchar esta sección</button></div></header><ol>';foreach($section[1] as $stepIndex=>$step)echo '<li><label><input type="checkbox" data-manual-step="'.$index.'-'.$stepIndex.'"><span><b>Paso '.($stepIndex+1).'</b>'.e($step).'</span></label></li>';echo '</ol><div class="manual-tip"><strong>Consejo visual</strong><div class="manual-visual"><span>① Selecciona</span><b>→</b><span>② Revisa</span><b>→</b><span>③ Confirma</span></div></div></article>'; }echo '<div class="card manual-empty" hidden>No encontramos ese tema. Prueba otra palabra.</div></div></div><footer class="manual-footer"><strong>FISITAAP</strong><span>Tu tienda, tus clientes y tus pedidos en un mismo lugar.</span></footer></main>';layout_end();
